import sys
def main():
    with open(os.path.join(P3,"runs/round89/batches.json"), encoding="utf-8") as f:
        batches = json.load(f)
    expected = set(batches["B03"]) | set(batches["B04"])
    entries = L1 + L2
    ids = [e["case_id"] for e in entries]
    assert len(ids) == len(set(ids)), "dup ids"
    assert set(ids) <= expected, "id outside B03/B04"
    if len(entries) == 40:
        assert set(ids) == expected, "full set must equal B03+B04 ids"
    os.makedirs(OUT, exist_ok=True)
    for e in entries:
        p = os.path.join(OUT, e["case_id"] + ".json")
        with open(p, "w", encoding="utf-8") as f:
            json.dump(e, f, ensure_ascii=False, indent=1)
    # verify each written file round-trips and id matches
    for cid in ids:
        with open(os.path.join(OUT, cid + ".json"), encoding="utf-8") as f:
            d = json.load(f)
        assert d["case_id"] == cid
        assert set(d.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}
    print(f"segment written: {len(ids)} ids={ids}")

if __name__ == "__main__":
    main()
